    title: "Little Hero Books — Test",
    pageImageUrls,
    coverPdfR2Key,           // preferred for W4
    // coverPdfUrl,           // uncomment to pass a direct URL instead
    shippingAddress,
    customer
  }
}];

// Guard Lulu Submit — always emit ONE item so Merge never blocks
// Input: JSON from "Supabase: get existing order" (array or object)

function fromNode(name) {
  try {
    const it = $items(name, 0, $itemIndex);
    return (Array.isArray(it) && it[0] && it[0].json) ? it[0].json : null;
  } catch { return null; }
}

// Normalize Supabase GET result (array → object)
let rows = $input.first()?.json ?? {};
if (Array.isArray(rows)) rows = rows[0] ?? {};

// Prefer richer upstream context (optional)
const upstream =
  fromNode('Build Lulu Print Job Payload') ||
  fromNode('Merge (after interior + meta)') ||
  fromNode('Validate & Normalize W4 Input') ||
  {};

const orderId         = upstream.orderId ?? rows.amazon_order_id ?? rows.orderId ?? 'ORDER';
const existingJobId   = rows.luluJobId ?? rows.lulu_job_id ?? null;
const existingStatus  = rows.lulu_status ?? rows.status ?? null;
const testMode        = Boolean(upstream?.CONFIG?.defaults?.testMode ?? upstream?.testMode);

// Base payload we always pass along
const out = {
  ...upstream,
  supabase: rows,       // keep original Supabase row for downstream use
};

// TEST MODE → bypass Lulu; synthesize a token response
if (testMode) {
  return [{
    json: {
      ...out,
      __skipLulu: true,
      id: `TEST-${orderId}`,
      status: 'TEST_MODE',
      guard: { reason: 'test_mode' },
    }
  }];
}

// Existing Lulu job recorded → bypass Lulu; return synthetic response
if (existingJobId) {
  return [{
    json: {
      ...out,
      __skipLulu: true,
      id: existingJobId,
      status: existingStatus || 'SUBMITTED',
      guard: { reason: 'existing_job' },
    }
  }];
}

// Proceed with submit → STILL emit one item so Merge has input #1
return [{
  json: {
    ...out,
    __skipLulu: false,
    guard: { reason: 'proceed' },
  }
}];

const resp = $input.first().json || {};
const access = resp.access_token || resp.token || resp.data?.access_token;
const expires = resp.expires_in || resp.data?.expires_in || null;
if (!access) throw new Error('SANDBOX token response missing access_token');
const issuedAt = new Date().toISOString();
return [{ json: { ...$json, luluAccessToken: access, luluTokenType: 'Bearer', luluTokenExpiresIn: expires, luluTokenIssuedAt: issuedAt } }];

const resp = $input.first().json || {};
const access = resp.access_token || resp.token || resp.data?.access_token;
