if (!access) throw new Error('PRODUCTION token response missing access_token');
const issuedAt = new Date().toISOString();
return [{ json: { ...$json, luluAccessToken: access, luluTokenType: 'Bearer', luluTokenExpiresIn: expires, luluTokenIssuedAt: issuedAt } }];

