  timestamp: new Date().toISOString()
};
console.log('W4 Status Banner →', banner);
return [{ json: { ...j, _statusBanner: banner } }];

const crypto = require('crypto');

const j = $input.first().json || {};
const cfg = j.CONFIG || {};
const { bucket, endpointHost, region, accessKeyId, secretAccessKey } = (cfg.r2 || {});

if (!bucket || !endpointHost || !accessKeyId || !secretAccessKey) {
  throw new Error('R2 config incomplete: bucket/endpointHost/accessKeyId/secretAccessKey required');
}

function isUrl(s) {
  return typeof s === 'string' && /^https?:\/\//i.test(s);
